        "mainEntity": [
          {
            "@type": "Question",
            "name": "How do I calculate a percentage of a number?",
            "acceptedAnswer": {
              "@type": "Answer",
              "text": "Multiply the number by the percent as a decimal: percent_of = base * (percent/100)."
            }
          },
          {
            "@type": "Question",
            "name": "How do I find what percent one number is of another?",
            "acceptedAnswer": {
              "@type": "Answer",
              "text": "Divide part by whole and multiply by 100: percent = (part/whole)*100."
            }
          },
          {
            "@type": "Question",
            "name": "How do I compute percentage change?",
            "acceptedAnswer": {
              "@type": "Answer",
              "text": "Use ((new - old) / old) * 100%. The base is the original value."
            }
          },
          {
            "@type": "Question",
            "name": "Why do my results look off?",
            "acceptedAnswer": {
              "@type": "Answer",
              "text": "Check whether you used the correct base and converted the percent to a decimal."
            }
          },
          {
            "@type": "Question",
            "name": "How do I reverse a percentage increase/discount?",
            "acceptedAnswer": {
              "@type": "Answer",
              "text": "Divide by (1 + p) for increases or by (1 - p) for discounts to recover the original."
            }
          }
        ]
